NS_IMETHODIMP nsMsgDBService::OpenDBFromFile(nsIFile* aDBPath,
                                             nsIMsgFolder* aFolder,
                                             bool aCreate, bool aLeaveInvalidDB,
                                             nsIMsgDatabase** pMessageDB) {
  AUTO_PROFILER_LABEL("nsMsgDBService::OpenDBFromFile", MAILNEWS);

  nsresult rv;
  MOZ_ASSERT(aDBPath);

  *pMessageDB = FindInCache(aDBPath);
  if (*pMessageDB) {
    return NS_OK;
  }

nsCOMPtr<nsIFile> backupDBFile;
rv =
    GetSummaryFileLocation(backupDBDummyFolder, getter_AddRefs(backupDBFile));
NS_ENSURE_SUCCESS(rv, rv);

nsCOMPtr<nsIMsgDBService> msgDBService =
    do_GetService("@mozilla.org/msgDatabase/msgDBService;1", &rv);
NS_ENSURE_SUCCESS(rv, rv);
rv = msgDBService->OpenDBFromFile(backupDBFile, this, false, true,
                                  getter_AddRefs(mBackupDatabase));

nsCOMPtr<nsIFile> newDBFile;
// "foo/bar/INBOX" -> "foo/bar/INBOX.msf"
rv = GetSummaryFileLocation(newPath, getter_AddRefs(newDBFile));
NS_ENSURE_SUCCESS(rv, rv);
rv = msgDBService->OpenDBFromFile(newDBFile, newMsgFolder, false, true,
                                  getter_AddRefs(destDB));
